const commands*: seq[CommandDecl] = collectCommands(packages)

const points*: seq[tuple[owner: string, point: PointDecl]] = collectPoints(packages)
  ## the extension points the packages define

const allFragments*: seq[Fragment] = collectFragments(packages)
  ## the schema: every package's fragments, in dependency order (after the database's own, `db/001-schema.sql`)

const schema*: seq[Fragment] = baseFragments & allFragments
  ## every fragment, the database's own first

proc newAllAccess*(mode: AccessMode): Access =
  ## The access rules for all the packages, in this `mode`.
  try:
    result = accessOf(packages, baseFragments & allFragments, mode)
  except PackageError as e:
    raiseAssert e.msg

let allAccess*: Access = newAllAccess(amEnforce)
  ## the rules `nch` and the tests run under

let extensions*: Extensions = collectExtensions(packages)
  ## what the packages contribute to each other (made when `nch` starts)
